serialized:
multiple_demod_threads = true;
multiple_output_threads = false;
stats_filepath = "/tmp/stats.txt";
localtime = true;
devices: (
  {
    type = "rtlsdr";
    serial = "1";
    gain = 29;
    centerfreq = 100000000;
    channels: (
      {
        freq = 100500000;
        outputs: (
          {
            type = "mixer";
            name = "mix1";
            ampfactor = 1.5;
            balance = -0.2;
          },
          {
            type = "mixer_remote";
            dest_path = "/run/x.sock";
            stream_id = 3;
            disable = false;
          }
        );
      }
    );
  }
);
mixers: {
  mix1: {
    disable = false;
    enabled = false;
    highpass = 200;
    lowpass = 3000;
    reserve_inputs = 2;
    remote_inputs: (
      {
        listen_path = "/run/mix1.sock";
        stream_id = 0;
        ampfactor = 1.2;
        balance = -0.3;
        label = "site2 ch1";
      },
      {
        listen_path = "/run/mix1.sock";
        stream_id = 1;
      }
    );
    outputs: (
      {
        type = "icecast";
        server = "s";
        port = 8000;
        mountpoint = "/m";
        username = "u";
        password = "p";
      }
    );
  };
  mix2: {
    outputs: (
      {
        type = "file";
        directory = "/tmp";
        filename_template = "m";
      }
    );
  };
};

